      assign gt_rx_ch_rxheadervalid[28*2 +: 4*2] = 'd0;
      assign gt_rx_ch_rxresetdone[28*1 +: 4*1] = 'd0;
      assign gt_rx_ch_rxbufstatus[28*3 +: 4*3] = 'd0;
      assign gt_rx_ch_rxprbserr[28*1 +: 4*1] = 'd0;
      assign gt_rx_ch_rxprbslocked[28*1 +: 4*1] = 'd0;
      assign gt_tx_ch_txresetdone[28*1 +: 4*1] = 'd0;
      assign gt_tx_ch_txbufstatus[28*2 +: 4*2] = 'd0;
    end

  end else begin : g_no_versal

    assign gt_rx_phy_clk_out = 'd0;
    assign gt_tx_phy_clk_out = 'd0;
    assign up_qm_rx_rdata = 'd0;
